  "strategy": "Ground the exact geometry diagram from the question screen, then read the visible labels/constraints needed to derive the shaded red area. Use frame evidence plus OCR so the refiner can compute the geometry from the actual on-screen givens rather than guessing from the answer choices.",
  "tool_calls": [
    {
      "step": 1,
      "tool": "frame_retriever",
      "arguments": {
        "video_path": "VIDEO",
        "query": "original geometry problem diagram showing a circle with center O, points P Q and R on the circumference, red shaded leaf-shaped regions, and the problem text",
        "timestamps": null,
        "num_frames": 3
      },
      "purpose": "Retrieve the key problem frame(s) containing the full diagram and visible givens before any later explanation state.",
      "depends_on": []
